{"description": "评测要求是自包含、无需新依赖并覆盖申请→审核→到访，我将直接写入一个可运行的 Node 原生访客预约应用与 README。", "file_path": "server.js", "content": "const http = require('http');
const fs = require('fs');
const path = require('path');
const PORT = process.env.PORT || 21000;
const dbFile = path.join(__dirname, 'visitors.json');
let applications = fs.existsSync(dbFile) ? JSON.parse(fs.readFileSync(dbFile, 'utf8')) : [
  {id:'V-1001', visitorName:'张伟', phone:'13800138000', company:'星河科技', hostName:'李娜', hostDept:'产品部', visitDate:'2026-07-28', visitTime:'09:30', reason:'项目沟通', status:'pending', createdAt:new Date().toISOString(), note:''}
];
function save(){fs.writeFileSync(dbFile, JSON.stringify(applications,null,2));}
function send(res, code, data, type='application/json'){res.writeHead(code, {'Content-Type':type+'; charset=utf-8','Access-Control-Allow-Origin':'*'});res.end(type==='application/json'?JSON.stringify(data):data)}
function body(req){return new Promise((ok, bad)=>{let s='';req.on('data',c=>s+=c);req.on('end',()=>{try{ok(s?JSON.parse(s):{})}catch(e){bad(e)}})})}
const html=fs.readFileSync(path.join(__dirname,'index.html'),'utf8');
const server=http.createServer(async (req,res)=>{
  if(req.method==='OPTIONS'){send(res,204,'');return}
  if(req.url==='/'||req.url==='/index.html'){send(res,200,html,'text/html');return}
  if(req.url==='/api/applications'&&req.method==='GET'){send(res,200,{applications});return}
  if(req.url==='/api/applications'&&req.method==='POST'){
    try{const d=await body(req); for(const k of ['visitorName','phone','hostName','visitDate','visitTime','reason']) if(!d[k]) return send(res,400,{error:`请填写${k}`});
      const a={id:'V-'+(1000+applications.length+1),company:d.company||'个人来访',hostDept:d.hostDept||'未填写',note:'',status:'pending',createdAt:new Date().toISOString(),...d};applications.unshift(a);save();send(res,201,a)
    }catch(e){send(res,400,{error:'请求格式错误'})}return
  }
  const m=req.url.match(/^\/api\/applications\/([^/]+)\/(approve|reject|checkin|checkout)$/);
  if(m&&req.method==='POST'){const a=applications.find(x=>x.id===m[1]);if(!a)return send(res,404,{error:'申请不存在'});const action=m[2];
    if(action==='approve'&&a.status==='pending'){a.status='approved';a.note='被访人已审核通过'}
    else if(action==='reject'&&a.status==='pending'){a.status='rejected';a.note='被访人审核未通过'}
    else if(action==='checkin'&&a.status==='approved'){a.status='checked_in';a.checkedInAt=new Date().toISOString()}
    else if(action==='checkout'&&a.status==='checked_in'){a.status='checked_out';a.checkedOutAt=new Date().toISOString()}
    else return send(res,409,{error:'当前状态不可执行该操作'});save();send(res,200,a);return}
  send(res,404,{error:'Not found'});
});server.listen(PORT,'0.0.0.0',()=>console.log(`Visitor system running at http://0.0.0.0:${PORT}`));
", "tags": ["visitor-system", "backend"]}

{"description": "后端状态机已落地，接着补齐申请端与审核/到访管理界面，确保评测可直接操作完整流程。", "file_path": "index.html", "content": "<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>访客通 · 访客预约管理</title><style>
:root{--ink:#172033;--muted:#6f7b91;--line:#e5eaf2;--brand:#3563e9;--bg:#f5f7fb;--green:#16845b;--orange:#c77812;--red:#c83d51}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px system-ui,-apple-system,"Microsoft Yahei",sans-serif}header{height:70px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 42px;gap:36px}.logo{font-size:21px;font-weight:800;color:var(--brand)}.logo span{color:#22a579}.nav{display:flex;gap:26px;color:var(--muted)}.nav b{color:var(--brand);border-bottom:2px solid var(--brand);padding:24px 0}.wrap{max-width:1240px;margin:30px auto;padding:0 24px}.hero{display:flex;justify-content:space-between;align-items:end;margin-bottom:25px}.hero h1{margin:0 0 8px;font-size:28px}.hero p{margin:0;color:var(--muted)}.tabs{display:flex;gap:4px;background:#eaf0ff;border-radius:10px;padding:4px}.tabs button{border:0;padding:9px 18px;background:transparent;border-radius:7px;color:var(--muted);cursor:pointer}.tabs .on{background:#fff;color:var(--brand);box-shadow:0 2px 7px #cbd5ed}.grid{display:grid;grid-template-columns:370px 1fr;gap:22px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:23px;box-shadow:0 3px 14px #1b31500a}.card h2{font-size:17px;margin:0 0 20px}.field{margin:13px 0}.field label{display:block;font-weight:650;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:10px 11px;border:1px solid #d8dfeb;border-radius:8px;outline:0;background:#fff}.field input:focus,.field textarea:focus{border-color:var(--brand);box-shadow:0 0 0 3px #3563e914}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.primary{width:100%;border:0;border-radius:8px;background:var(--brand);color:white;padding:12px;font-weight:700;cursor:pointer;margin-top:8px}.stats{display:flex;gap:10px;margin-bottom:16px}.stat{flex:1;background:#f8faff;border-radius:9px;padding:13px}.stat strong{display:block;font-size:21px}.stat small{color:var(--muted)}.filters{display:flex;justify-content:space-between;align-items:center;margin-bottom:13px}.filters input{padding:9px;border:1px solid var(--line);border-radius:7px;width:220px}.item{border:1px solid var(--line);border-radius:11px;padding:16px;margin:10px 0}.itemtop{display:flex;justify-content:space-between;align-items:start}.name{font-size:16px;font-weight:750}.meta{color:var(--muted);line-height:1.8;margin-top:7px}.badge{padding:4px 9px;border-radius:20px;font-size:12px;font-weight:700}.pending{background:#fff4dd;color:var(--orange)}.approved{background:#e3f7ee;color:var(--green)}.rejected{background:#ffeaed;color:var(--red)}.checked_in{background:#e3efff;color:#2462b8}.checked_out{background:#edf0f4;color:#657083}.actions{display:flex;gap:7px;margin-top:12px}.actions button{border:1px solid #d8dfeb;background:white;border-radius:6px;padding:7px 12px;cursor:pointer}.actions .ok{background:var(--green);border-color:var(--green);color:white}.actions .danger{color:var(--red)}.empty{text-align:center;color:var(--muted);padding:45px}#toast{position:fixed;right:25px;bottom:25px;background:#172033;color:#fff;padding:12px 18px;border-radius:8px;display:none}@media(max-width:850px){.grid{grid-template-columns:1fr}header{padding:0 18px}.wrap{padding:0 14px}.nav{display:none}}
</style></head><body><header><div class="logo">访客<span>通</span></div><div class="nav"><b>访客预约</b><span>访客记录</span><span>园区设置</span></div><div style="margin-left:auto;color:var(--muted)">管理后台　⌄</div></header><main class="wrap"><div class="hero"><div><h1>访客预约</h1><p>让每一次到访，都有清晰的安排与记录</p></div><div class="tabs"><button id="applyTab" class="on" onclick="show('apply')">提交来访申请</button><button id="manageTab" onclick="show('manage')">审核与到访管理</button></div></div><section id="apply" class="grid"><div class="card"><h2>填写访客申请</h2><form id="form"><div class="field"><label>访客姓名 <i>*</i></label><input name="visitorName" placeholder="请输入真实姓名" required></div><div class="row"><div class="field"><label>联系电话 <i>*</i></label><input name="phone" placeholder="手机号" required></div><div class="field"><label>所在公司</label><input name="company" placeholder="公司名称"></div></div><div class="row"><div class="field"><label>被访人 <i>*</i></label><input name="hostName" placeholder="姓名" required></div><div class="field"><label>所属部门</label><input name="hostDept" placeholder="如：产品部"></div></div><div class="row"><div class="field"><label>到访日期 <i>*</i></label><input type="date" name="visitDate" required></div><div class="field"><label>到访时间 <i>*</i></label><input type="time" name="visitTime" required></div></div><div class="field"><label>来访事由 <i>*</i></label><textarea name="reason" rows="3" placeholder="请说明来访目的" required></textarea></div><button class="primary">提交审核</button></form></div><div class="card"><h2>申请流程</h2><div style="display:flex;gap:16px;margin:30px 0"><div style="color:var(--brand);font-size:25px">①</div><div><b>提交来访申请</b><p style="color:var(--muted)">填写访客及被访人信息</p></div></div><div style="display:flex;gap:16px;margin:30px 0"><div style="color:var(--brand);font-size:25px">②</div><div><b>被访人审核</b><p style="color:var(--muted)">审核通过后方可登记到访</p></div></div><div style="display:flex;gap:16px;margin:30px 0"><div style="color:var(--brand);font-size:25px">③</div><div><b>到访登记</b><p style="color:var(--muted)">前台核验后登记进出时间</p></div></div></div></section><section id="manage" style="display:none"><div class="stats"><div class="stat"><small>待审核</small><strong id="pendingN">0</strong></div><div class="stat"><small>今日已预约</small><strong id="todayN">0</strong></div><div class="stat"><small>当前在访</small><strong id="inN">0</strong></div></div><div class="card"><div class="filters"><h2 style="margin:0">访客申请列表</h2><input id="search" placeholder="搜索访客/被访人" oninput="render()"></div><div id="list"></div></div></section></main><div id="toast"></div><script>
let data=[];const labels={pending:'待审核',approved:'已通过',rejected:'已拒绝',checked_in:'已到访',checked_out:'已离场'};const today=new Date().toISOString().slice(0,10);
async function load(){data=(await fetch('/api/applications').then(r=>r.json())).applications;render()}function show(x){document.getElementById('apply').style.display=x==='apply'?'grid':'none';document.getElementById('manage').style.display=x==='manage'?'block':'none';document.getElementById('applyTab').className=x==='apply'?'on':'';document.getElementById('manageTab').className=x==='manage'?'on':'';if(x==='manage')load()}
function render(){let q=(document.getElementById('search')?.value||'').toLowerCase();let arr=data.filter(a=>(a.visitorName+a.hostName+a.company).toLowerCase().includes(q));pendingN.textContent=data.filter(a=>a.status==='pending').length;todayN.textContent=data.filter(a=>a.visitDate===today).length;inN.textContent=data.filter(a=>a.status==='checked_in').length;list.innerHTML=arr.length?arr.map(a=>`<div class="item"><div class="itemtop"><div><div class="name">${a.visitorName} <span style="font-size:12px;color:#8993a5">${a.company||''}</span></div><div class="meta">被访人：${a.hostName} · ${a.hostDept||'—'}<br>预约：${a.visitDate} ${a.visitTime}　|　事由：${a.reason}</div></div><span class="badge ${a.status}">${labels[a.status]}</span></div><div class="actions">${a.status==='pending'?`<button class="ok" onclick="act('${a.id}','approve')">通过审核</button><button class="danger" onclick="act('${a.id}','reject')">拒绝</button>`:''}${a.status==='approved'?`<button class="ok" onclick="act('${a.id}','checkin')">登记到访</button>`:''}${a.status==='checked_in'?`<button onclick="act('${a.id}','checkout')">登记离场</button>`:''}<span style="margin-left:auto;color:#a0a8b5;font-size:12px">申请编号 ${a.id}</span></div></div>`).join(''):'<div class="empty">暂无匹配的访客申请</div>'}
async function act(id,action){let r=await fetch('/api/applications/'+id+'/'+action,{method:'POST'});let x=await r.json();if(!r.ok)return toast(x.error);toast('操作成功');load()}function toast(s){let t=document.getElementById('toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',2200)}form.onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(form));let r=await fetch('/api/applications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});if(r.ok){form.reset();toast('申请已提交，等待被访人审核');show('manage');}else toast((await r.json()).error)};load();
</script></body></html>
